import { Component, ElementRef, EventEmitter, HostListener, Input, Output } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { toolEvents } from '../../interfaces/pdf.interface';
import { CommonModule, NgClass } from '@angular/common';
import { MatTooltipModule } from '@angular/material/tooltip';





@Component({
  selector: 'fabbutton',
  standalone: true,
  imports: [IconComponent, CommonModule, MatTooltipModule, TranslateModule],
  templateUrl: './fabbutton.component.html',
  styleUrl: './fabbutton.component.scss'
})
export class FabbuttonComponent {

  @Output() buttonClick = new EventEmitter<toolEvents>();

  @Input() isHost: boolean;

  threeButtonConfig: any = {
    radius: 70,
    buttonSize: 35,
    mainButtonSize: 45,
    animationDuration: 300,
    animationDelay: 50,
    buttonGap: 20,
    buttons: [
      { icon: 'fact', label: 'FABBUTTON.FACT', value: 'F', active: true },
      { icon: 'doclink', label: 'FABBUTTON.DOC_LINK', active: true, value: 'D' },
      { icon: 'weblink', label: 'FABBUTTON.WEB_LINK', active: true, value: 'W' }
    ]
  };

  // Four button configuration
  fourButtonConfig: any = {
    radius: 70,
    buttonSize: 35,
    mainButtonSize: 45,
    animationDuration: 300,
    animationDelay: 50,
    buttonGap: 20,
    buttons: [
      { icon: 'fact', label: 'FABBUTTON.FACT', value: 'F', active: true },
      { icon: 'doclink', label: 'FABBUTTON.DOC_LINK', active: true, value: 'D' },
      { icon: 'weblink', label: 'FABBUTTON.WEB_LINK', active: true, value: 'W' },
      { icon: 'share', type: 'extra', label: 'FABBUTTON.SHARED_MARKING', active: true, value: 'S' }
    ]
  };

  // You can switch between configurations
  currentConfig = this.threeButtonConfig;

  isOpen = false;


  @Input() fabIcons: string[] = ['F', 'D', 'W', 'S'];
  @Output() fabIconsChange = new EventEmitter<string[]>();
  constructor(private elementRef: ElementRef) { }

  ngOnInit() {
    this.currentConfig =
      this.isHost ?
        this.threeButtonConfig
        :
        this.fourButtonConfig
    this.calculateButtonPositions();
  }

  ngOnChanges() {
    this.calculateButtonPositions();
  }

  private getAngleConfig(buttonCount: number): { startAngle: number, endAngle: number } {
    // Convert degrees to radians for calculations
    const degToRad = (deg: number) => deg * (Math.PI / 180);

    switch (buttonCount) {
      case 3:
        return {
          startAngle: degToRad(-45),  // 30 degrees from top
          endAngle: degToRad(53)    // 145 degrees towards bottom
        };
      case 4:
        return {
          startAngle: degToRad(-90), // -60 degrees from top
          endAngle: degToRad(90)    // 160 degrees towards bottom
        };
      default:
        return {
          startAngle: degToRad(-90), // Default to full 180 spread
          endAngle: degToRad(90)
        };
    }
  }

  private calculateButtonPositions(): void {
    const totalButtons = this.currentConfig.buttons.length;
    if (totalButtons <= 1) return;

    // Get angle currentConfiguration based on number of buttons
    const anglecurrentConfig = this.getAngleConfig(totalButtons);
    const angleSpread = anglecurrentConfig.endAngle - anglecurrentConfig.startAngle;
    const angleStep = angleSpread / (totalButtons - 1);

    this.currentConfig.buttons = this.currentConfig.buttons.map((button, index) => {
      const angle = anglecurrentConfig.startAngle + (index * angleStep);
      const x = this.currentConfig.radius * Math.cos(angle);
      const y = this.currentConfig.radius * Math.sin(angle);

      return {
        ...button,
        position: {
          left: `${x}px`,
          top: `${y}px`
        }
      };
    });
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent) {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      this.closeMenu();
    }
  }

  @HostListener('document:keydown.escape')
  onEscapePress() {
    this.closeMenu();
  }

  toggleMenu(event: MouseEvent) {
    event.stopPropagation();
    this.isOpen = !this.isOpen;
  }

  closeMenu() {
    if (this.isOpen) {
      this.isOpen = false;
    }
  }

  onButtonClick(button: any) {
    button.active = !button.active;


    if (button.active) {
      if (!this.fabIcons.includes(button.value)) {
        this.fabIcons.push(button.value);
      }
    } else {
      this.fabIcons = this.fabIcons.filter(icon => icon != button.value);
    }
    this.fabIconsChange.emit(this.fabIcons);

    this.buttonClick.emit({ event: `TOGGLE-ANNOT`, data: this.fabIcons });
  }

}
