  keyCase(key: string): string {
    if (!this.BLACKLIST.includes(key)) {
      key = key.replace(this.UPPER_REGEX, (match) => '-' + match.toLowerCase());
    }
    return key;
  }

  setPen(penSize: any = 1, penColor: string = '#000000') {
    this._penSize = Math.round(parseFloat(penSize) * 1e2) / 1e2;
    this._penColor = penColor;
  }

  transform(node: any, viewport: PDFPageViewport): HTMLElement {
    const trans = this.getTranslation(viewport);
    node.setAttribute('transform', `scale(1) rotate(${viewport.rotation}) translate(${trans.x}, ${trans.y})`);
    /* if (!this.isFirefox && node.nodeName.toLowerCase() === 'svg') {
      this.adjustNodeDimensions(node, viewport);
     }*/
    return node;
  }
  getAnnotationType(modeltype: any): string {
    if (['QF', 'F'].includes(modeltype)) {
      return 'highlight';
    }
    return modeltype === 'D' ? 'strikeout1' : 'strikeout';
  }


  convertToSvgRect = (rect: any, viewport: PDFPageViewport) => {
    let pt1 = [rect.x, rect.y];
    let pt2 = [rect.x + rect.width, rect.y + rect.height];

    pt1 = this.convertToSvgPoint(pt1, viewport);
    pt2 = this.convertToSvgPoint(pt2, viewport);

    return {
      x: Math.min(pt1[0], pt2[0]),
      y: Math.min(pt1[1], pt2[1]),
      width: Math.abs(pt2[0] - pt1[0]),
      height: Math.abs(pt2[1] - pt1[1])
    };
  }

  convertToSvgPoint = (pt: any, viewport: PDFPageViewport) => {

    viewport = viewport;// || this.getMetadata(svg).viewport;

    let xform = [1, 0, 0, 1, 0, 0];
    xform = this.scale(xform, viewport.scale, viewport.scale);
    xform = this.rotate(xform, viewport.rotation);

    let offset = this.getTranslation(viewport);
    xform = this.translate(xform, offset.x, offset.y);

    return this.applyInverseTransform(pt, xform);
  }
  scale = (m: any, x: any, y: any) => {
    return [
      m[0] * x,
      m[1] * x,
      m[2] * y,
      m[3] * y,
      m[4],
      m[5]
    ];
  };
  rotate = (m: any, angle: any) => {
    angle = angle * Math.PI / 180;

    let cosValue = Math.cos(angle);
    let sinValue = Math.sin(angle);

    return [
      m[0] * cosValue + m[2] * sinValue,
      m[1] * cosValue + m[3] * sinValue,
      m[0] * (-sinValue) + m[2] * cosValue,
      m[1] * (-sinValue) + m[3] * cosValue,
      m[4],
      m[5]
    ];
  };
  translate = (m: any, x: any, y: any) => {
    return [
      m[0],
      m[1],
      m[2],
      m[3],
      m[0] * x + m[2] * y + m[4],
      m[1] * x + m[3] * y + m[5]
    ];
  };

  getSelectionRects = () => {
    // Mirrors PDF.js v25's AnnotationEditorUIManager.getSelectionBoxes
    // (node_modules/ngx-extended-pdf-viewer/assets/viewer-5.4.1105.mjs
    // line 11068). Three things this brings over the previous
    // implementation:
    //
    //   1. textLayer containment validation. We resolve the page from
    //      the selection's first range, then reject the whole capture
    //      if ANY range escapes that page's `.textLayer` div. Catches
    //      stray selections that started in a sidebar, toolbar, or
    //      wrapping container and dragged into the PDF — those used to
    //      sneak through and produce phantom rects on save. Also
    //      rejects cross-page selections (where the common ancestor is
    //      above multiple `.textLayer` divs); we save by single page,
    //      so cross-page rects would land on the wrong page anyway.
    //
    //   2. Zero-size rect filter at capture time. Upstream filters in
    //      the same loop that walks `range.getClientRects()`; we used
    //      to only check the first rect. A selection where rect[0] is
    //      a zero-width caret artifact at the start would be rejected
    //      wholesale even if the rest were valid.
    //
    //   3. Multi-range loop. The DOM Selection API supports multiple
    //      ranges (Ctrl/Cmd-click composite selections). The previous
    //      implementation only read range 0; this collects from all of
    //      them and drops collapsed ranges, matching upstream.
    //
    // We return absolute pixel coords (not the page-relative 0-1 coords
    // PDF.js's editor uses internally) because our downstream pipeline
    // — markHighlight, saveRect, the SVG renderer — expects pixels.
    // Rotation is applied later via pageRotation in saveRect, not here.
    try {
      const selection: any = window.getSelection();
      if (!selection || selection.rangeCount === 0) return null;

      const range0 = selection.getRangeAt(0);
      if (range0.collapsed) return null;

      // Resolve the page from the first range's common ancestor.
      // commonAncestorContainer is often a Text node — climb to its
      // element parent before calling closest().
      let ancestor: any = range0.commonAncestorContainer;
      if (ancestor && ancestor.nodeType === Node.TEXT_NODE) {
        ancestor = ancestor.parentElement;
      }
      const pageEl: HTMLElement | null = ancestor?.closest?.('.page') ?? null;
      if (!pageEl) return null;

      const pg = parseInt(pageEl.getAttribute('data-page-number') || '');
      if (!pg) return null;

      const textLayer = pageEl.querySelector('.textLayer') as HTMLElement | null;
      if (!textLayer) return null;

      // Containment check (PDF.js getSelectionBoxes semantics).
      for (let i = 0; i < selection.rangeCount; i++) {
        const range = selection.getRangeAt(i);
        let container: any = range.commonAncestorContainer;
        if (container && container.nodeType === Node.TEXT_NODE) {
          container = container.parentElement;
        }
        if (!textLayer.contains(container)) return null;
      }

      // Collect rects from every non-collapsed range, dropping zero-
      // size entries inline (matches upstream loop).
      const rects: { top: number; left: number; width: number; height: number }[] = [];
      for (let i = 0; i < selection.rangeCount; i++) {
        const range = selection.getRangeAt(i);
        if (range.collapsed) continue;
        for (const r of range.getClientRects()) {
          if (r.width <= 0 || r.height <= 0) continue;
          rects.push({ top: r.top, left: r.left, width: r.width, height: r.height });
        }
      }

      if (!rects.length) return null;

      return { rects, page: pg, text: selection.toString() };
    } catch {
      return null;
    }
  }

  getAllSVGAnnots(SVG: SVGElement | SVGAElement | null) {
    return SVG ? SVG.querySelectorAll('[uuid]') : [];
  }

  pointIntersectsRect = (x, y, rect) => {
    return y >= rect.top && y <= rect.bottom && x >= rect.left && x <= rect.right;
  }

  getBoundingClientRect(element: any) {
    const rect = element.getBoundingClientRect();
    return {
      top: rect.top,
      right: rect.right,
      bottom: rect.bottom,
      left: rect.left,
      width: rect.width,
      height: rect.height,
      x: rect.x,
      y: rect.y
    };
  }
