import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { CommonModule, DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { MatFormFieldModule } from '@angular/material/form-field';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { InputComponent } from '../../../shared/components/input/input.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { TeamshareComponent } from '../../../marking/components/fact/teamshare/teamshare.component';
import { DocInfo } from '../../interfaces/pdf.interface';
import { IndividualService } from '../../../userpanel/services/individual/individual.service';
import { CommonService } from '../../../shared/services/common/common.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Component({
  selector: 'app-document-share',
  standalone: true,
  imports: [
    FormsModule,
    MatCheckboxModule,
    MatSelectModule,
    MatFormFieldModule,
    ButtonComponent,
    IconComponent,
    TeamshareComponent, DatePipe, TranslateModule, CommonModule
  ],
  templateUrl: './document-share.component.html',
  styleUrl: './document-share.component.scss'
})
export class DocumentShareComponent {
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() Dialogtype: string = 'DS';
  @Output() DialogtypeChange: EventEmitter<string> = new EventEmitter<string>();
  selectedShareType: 'E' | 'Q' = 'E';
  includeDocName: boolean = true;
  expiryDays: number = 7;
  expiryDate: Date = new Date(Date.now() + this.expiryDays * 24 * 60 * 60 * 1000);
  documentUrl: string = 'https://etabella.tech/individual/doc/%5B%5B%5B%22c70a07ea-084f-...';
  documentName: string = 'First Defendant\'s Supporting Document Addendum - Amended';
  bundleReference: string = '[ B | 2A | 43-44 ]';

  // Expiry options for the dropdown
  expiryOptions = [
    { value: 1, label: 'DOCUMENT_SHARE.EXPIRY_OPTIONS.24_HOURS' },
    { value: 7, label: 'DOCUMENT_SHARE.EXPIRY_OPTIONS.7_DAYS' },
    { value: 30, label: 'DOCUMENT_SHARE.EXPIRY_OPTIONS.30_DAYS' },
  ];


  @Input() nId: string = null;
  @Input() isLocationShared: boolean = false;
  @Input() nCaseid: string = null;
  @Input() nUserid: string;
  @Input() type: string = ''; // "F/W/D"
  userList: any[] = [];
  constructor(private individualS: IndividualService, private cdr: ChangeDetectorRef, private common: CommonService, private tost: TostbarService, private translate: TranslateService) {

  }


  async ngOnInit() {
    const nFSid = this.nId;

    if (this.isLocationShared || (this.type == 'F' && nFSid)) {
      const users = await this.individualS.sharedusers(this.docInfo.nBundledetailid) || [];
      // this.userList.map(f => f.isSelected = (users.findIndex(m => m.nUserid == f.nUserid) > -1))


      if (this.docInfo) {
        this.documentUrl = `${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([[[this.docInfo.nBundledetailid, 1, 0, nFSid || null]], this.nCaseid]))}`;
        this.documentName = this.docInfo.cFilename;
        this.bundleReference = `[ ${this.docInfo?.['cBundletag']} | ${this.docInfo?.cTab} | ${this.docInfo?.cRefpage || this.docInfo?.cPage} ]`
      }

      this.cdr.detectChanges();
    }
    this.getMyTeamUsers();
  }

  isCopied: boolean = false;

  copyToClipboard() {

    if (this.isCopied) {
      return;
    }

    navigator.clipboard.writeText(this.documentUrl).then(() => {
      this.isCopied = true;
      setTimeout(() => {
        this.isCopied = false;
        this.cdr.detectChanges();
      }, 2000);
      this.cdr.detectChanges();
    });
  }

  onShareTypeChange(type: 'E' | 'Q') {
    this.selectedShareType = type;
  }

  onCheckboxChange(checked: boolean) {
    this.includeDocName = checked;
  }

  onExpiryChange(value: number) {
    this.expiryDays = value;
    this.expiryDate = new Date(Date.now() + this.expiryDays * 24 * 60 * 60 * 1000);
  }

  async getMyTeamUsers() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    if (this.userList?.length) {
      this.userList = this.userList.filter(x => x.nUserid != this.nUserid);
    }
  }

  async sendInvitation() {
    const mdl = {
      nBundledetailid: this.docInfo.nBundledetailid,
      jUsers: JSON.stringify(this.userList.filter(f => f.isSelected).map(m => m.nUserid)),
    }

    const res = await this.individualS.shared_to_users(mdl);
    if (res) {
      this.DialogtypeChange.emit(null);
      this.tost.openSnackBar(this.translate.instant('DOCUMENT_SHARE.INVITATION_SENT'), '');
    }
    this.cdr.detectChanges();
  }
}
