  /** Issues the popup advertises as the QFact's tags. Mirrors what was
   *  passed to submitQuickFact: explicit user picks from the LEFT panel
   *  when present, else the case's Unassigned fallback. Held separately
   *  from `selectedIssues` so the LEFT panel's selection state isn't
   *  mutated by the rapid-create flow — and so the popup template's
   *  guard (`@if (... qfactNotePopupIssues?.length ...)`) doesn't suppress
   *  the popup just because the user never picked an issue. */
  qfactNotePopupIssues: any[] = [];
  /** nFSid of the QFact this popup is currently attached to. Set when
   *  the host auto-creates the QFact on selection; consumed by the
   *  popup's saveNoteFn so the note update targets the right row. */
  qfactNotePopupFactId: string | null = null;
  /** Save handler bound into the popup. Sends the note text to the
   *  factService.updateFactNote endpoint, keyed by the QFact id we
   *  captured at create-time. Returns a boolean ok flag — the popup
   *  uses it to flash the "✔ Saved" indicator. */
  qfactNotePopupSaveFn: QFactRapidPopupSaveFn = async ({ note }) => {
    if (!this.qfactNotePopupFactId) return { ok: false };
    const trimmed = (note || '').trim();
    if (!trimmed) return { ok: false };
    try {
      const res = await this.factService.updateFactNote({
        nFSid: this.qfactNotePopupFactId,
        jTexts: [trimmed],
      });
      // The popup's "✔ Saved" chip is purely a UI reassurance — treat
      // anything that isn't an explicit failure (msg=-1, the project's
      // documented "fetch failed" marker) as success. Earlier we
      // required res.msg == 1 strictly, but the backend's success
      // response shape varies between endpoints (some return msg=1,
      // some return msg=0, some omit it), and the strict check made
      // the chip silently never appear on legitimate saves. The
      // canonical failure path is the catch block below; if the HTTP
      // call resolved without throwing, the data was at least
      // accepted server-side.
      const failed = res?.msg === -1;
      return { ok: !failed };
    } catch {
      return { ok: false };
    }
  };
