  spredmodeChnage(mode: "off" | "even" | "odd") {
    this.spreadMode = mode;
    if (mode == 'off') {
      this.zoom = 'page-actual';
    } else {
      this.zoom = 'page-width';
    }
    // Spread toggles trigger ngx-extended-pdf-viewer to re-render every
    // page with a NEW viewport (different scale + layout). The stored
    // pageViewports map still holds the OLD viewports until each page's
    // onPageRendered fires again — and if the user highlights between
    // the toggle and the re-render, markHighlight uses a stale viewport
    // and the annotation lands on the wrong line / off the page entirely.
    // Clearing the map up front forces markHighlight to bail-or-wait
    // until a fresh viewport is available (see the validation in
    // markHighlight). scale_factor is similarly invalidated and
    // recomputed once the new --scale-factor CSS var has been written.
    this.pageViewports.clear();
    this.scale_factor = null;
    requestAnimationFrame(() => {
      // rAF after the synchronous detectChanges below — by then
      // ngx-extended-pdf-viewer has applied the new spread/zoom and
      // the .page element's --scale-factor reflects the new layout.
      this.updateCurrentScaleFactor();
    });
    this.cdr.detectChanges();
  }

  async enterFullscreen() {
    const root: any = document.documentElement; // or: document.body
    try {
      const req = root.requestFullscreen || root.webkitRequestFullscreen || root.msRequestFullscreen;
      if (req) await req.call(root);
    } catch (err) {
      this.onFsError(new Event('fullscreenerror'));
      this.handleError(err, undefined, true);
    }
  }

  async exitFullscreen() {
    const d: any = document;
    try {
      const ex = document.exitFullscreen || d.webkitExitFullscreen || d.msExitFullscreen;
      if (ex) await ex.call(document);
    } catch (err) {
      this.onFsError(new Event('fullscreenerror'));
      this.handleError(err, undefined, true);
    }
  }

  @HostListener('document:keydown', ['$event'])
  onCalloutKeydown(e: KeyboardEvent) {
    if (e.key === 'Escape' && this.calloutOverlayActive) {
      e.preventDefault();
      e.stopPropagation();
      this.exitCalloutMode();
    }
  }

  @HostListener('document:fullscreenchange') onFsChangeStd() { this.handleFsChange(); }
  @HostListener('document:webkitfullscreenchange') onFsChangeWebkit() { this.handleFsChange(); }
  @HostListener('document:msfullscreenchange') onFsChangeMs() { this.handleFsChange(); }

  private handleFsChange() {
    this.isFullScreen = !this.isFullScreen;
    this.lastFsTrigger = 'unknown';
  }

