import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { DocInfo, hyperlinkOption, toolEvents } from '../../interfaces/pdf.interface';
import { PdfDataService } from '../../service/pdf-data.service';
import { SourceCardComponent } from '../../../shared/components/source-card/source-card.component';

@Component({
  selector: 'hyperlink-box',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SourceCardComponent],
  templateUrl: './hyperlink-box.component.html',
  styleUrl: './hyperlink-box.component.scss'
})
export class HyperlinkBoxComponent {
  @Input() hyperlinkOption: hyperlinkOption = {} as hyperlinkOption;
  inProcess: boolean = true;
  hyperlinkList: DocInfo[] = [];
  @Output() onHyperlinkEvent = new EventEmitter<toolEvents>();
  constructor(private pdfData: PdfDataService, private cdr: ChangeDetectorRef) {

  }

  async ngOnInit() {
    this.inProcess = true;
    this.hyperlinkList = [];
    this.cdr.detectChanges();
    if (this.hyperlinkOption.nBundledetailid && this.hyperlinkOption.isOpen) {
      this.onHyperlinkEvent.emit({ event: 'OPEN-HYPERLINK-FILE', data: { ...this.hyperlinkOption } });
      return;
    }
    if (this.hyperlinkOption?.nBundledetailid || this.hyperlinkOption.nDocid) {
      const res: any = await this.pdfData.getHyperLinkFile(this.hyperlinkOption.nBundledetailid, this.hyperlinkOption.nDocid || null);
      this.inProcess = false;
      if (res && res.length) {
        this.hyperlinkList = res;
      }
      this.cdr.detectChanges();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (!changes["hyperlinkOption"].firstChange && changes["hyperlinkOption"].currentValue?.nBundledetailid != changes["hyperlinkOption"].previousValue?.nBundledetailid) {
      console.warn('CANGES', changes["hyperlinkOption"].currentValue)
      this.ngOnInit();
    }
  }

  OpenFile(x) {
    this.onHyperlinkEvent.emit({ event: 'OPEN-HYPERLINK-FILE', data: { ...this.hyperlinkOption, ...x } });
  }

}
