import { feedAnnotCordinates } from "./annotation.interface";

export interface PageParsedItem extends Array<any> {
    0: string;       // time
    1: number[];     // asciiValue
    2: number;       // lineIndex
    3: string;       // formate
    4: number;       // oPage
    5: number;       // oLine
    6: string;       // unicid
    7: any[];        // links
}



export interface finalFeedData {
    time: string;
    lineIndex: number;
    lines: string[];

    isBold?: boolean;

    formate?: string;
    oPage?: number;
    oLine?: number;
    unicid?: string;
    links?: string[];

    nHid?: string

}


export interface transcriptData extends finalFeedData {
}


export interface feedPage {
    nSesid?: string;
    page: number;
    data: PageParsedItem[] | transcriptData[];
}


export interface liveFeedPage {
    date?: string; // this is an nSesid
    d: PageParsedItem[];
}



export interface refreshFeedPage {
    nSesid: string;
    start: string;
    end: string;
    newLines: PageParsedItem[];
    current_refresh:number;
}


export interface feedResponse {
    total: number;
    feed: feedPage[]
}


export type feedEventType = 'FEED-FAILED' | 'SCROLL-TO-LAST' | 'FEED-SUBJECT-REINITILIZE' | 'ANNOT-DETAILS' | 'SCROLL-TO-PAGE' | 'ANNOT-RENDERED' | 'QMARK-CREATED' | 'QMARK-DELETED' | 'SCROLL-TO-LINE' | 'VIEW-DOC-LINK' | 'QUICK-FACT-ADDED' | 'QUICK-FACT-UPDATED' | 'FACT-ADDED' | 'DOC-ADDED' | 'CLOSE' | 'DELETE-ANNOTATION' | 'EDIT' | 'OPEN-COMPARE-MODE' | 'FEED-PAUSED' | 'FEED-RESUMED' | 'FEED-UPDATED' | 'FILTER-ANNOTATION';
export interface SessionEvent {
    type: feedEventType;
    data?: any;
}

export const FEED_EVENT_TYPES = {
    FEED_FAILED: 'FEED-FAILED',
    SCROLL_TO_LAST: 'SCROLL-TO-LAST',
    FEED_SUBJECT_REINITILIZE: 'FEED-SUBJECT-REINITILIZE',
    ANNOT_DETAILS: 'ANNOT-DETAILS',
    SCROLL_TO_PAGE: 'SCROLL-TO-PAGE',
    ANNOT_RENDERED: 'ANNOT-RENDERED',
    QMARK_CREATED: 'QMARK-CREATED',
    QMARK_DELETED: 'QMARK-DELETED',
    SCROLL_TO_LINE: 'SCROLL-TO-LINE',
    VIEW_DOC_LINK: 'VIEW-DOC-LINK',
    QUICK_FACT_ADDED: 'QUICK-FACT-ADDED',
    QUICK_FACT_UPDATED: 'QUICK-FACT-UPDATED',
    FACT_ADDED: 'FACT-ADDED',
    DOC_ADDED: 'DOC-ADDED',
    CLOSE: 'CLOSE',
    DELETE_ANNOTATION: 'DELETE-ANNOTATION',
    EDIT: 'EDIT',
    OPEN_COMPARE_MODE: 'OPEN-COMPARE-MODE',
    FEED_PAUSED: 'FEED-PAUSED',
    FEED_RESUMED: 'FEED-RESUMED',
    FEED_UPDATED: 'FEED-UPDATED',
    FILTER_ANNOTATION: 'FILTER-ANNOTATION',
} as const;

export interface linkLines {
    x: number;
    y: number;
    color: string;
    iconX: number;
    iconY: number;
    id: string;
    layoutHeight?: number;
}

type annotRefreshType = 'A' | 'H' | 'QF' | 'F' | 'D';

export interface annotRefreshData {
    nId: string;
    cType: annotRefreshType;
    nHid: string;
    cONote: string;
    jCordinates: feedAnnotCordinates[];
    cPageno: string;
    cLineno: string;
    nUserid: string;
    isInActivated: boolean;
}

export interface highlightRefreshData {
    nHid: string;
    cPageno: string;
    cLineno: string;
    cTime: string;
    cNote: string;
    identity: string;
    isMain: boolean;
    nUserid: string;

}


export interface annotTransferEvent {
    nSesid: string;
    cType: annotRefreshType;
    data: annotRefreshData[] | highlightRefreshData[];
}

export interface activeFeedData {
    item: finalFeedData;
    page: number;
    index: number;
}